grid = [
    [0, 3, 3, 8, 3, 0],
    [0, 8, 3, 0, 3, 3],
    [3, 0, 3, 3, 3, 3],
    [3, 0, 3, 3, 3, 8],
    [9, 3, 0, 9, 8, 3],
    [0, 3, 0, 3, 8, 8],
    [3, 8, 0, 3, 3, 0],
    [9, 9, 8, 0, 8, 0]
]

output_grid = []
for i in range(len(grid)):
    row = []
    for j in range(len(grid[0])):
        adj_to_zero = False
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                    if grid[ni][nj] == 0:
                        adj_to_zero = True
                        break
            if adj_to_zero:
                break

        # Output 1 if adj to zero, else 0
        row.append(1 if adj_to_zero else 0)
    output_grid.append(row)

print("Adjacent to zero = 1:")
for r in output_grid:
    print(r)

# For each cell: bitwise AND of all neighbor values (excluding self)
grid = [
    [0, 3, 3, 8, 3, 0],
    [0, 8, 3, 0, 3, 3],
    [3, 0, 3, 3, 3, 3],
    [3, 0, 3, 3, 3, 8],
    [9, 3, 0, 9, 8, 3],
    [0, 3, 0, 3, 8, 8],
    [3, 8, 0, 3, 3, 0],
    [9, 9, 8, 0, 8, 0]
]

output_grid = []
for i in range(len(grid)):
    row = []
    for j in range(len(grid[0])):
        # Bitwise AND of all neighbors (need at least one, initialize as identity for AND = 0xFF for now but we only consider actual neighbors)
        and_result = None

        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                    val = grid[ni][nj]
                    if and_result is None:
                        and_result = val
                    else:
                        and_result &= val

        # If no neighbors (shouldn't happen here), use original value
        if and_result is None:
            and_result = grid[i][j]

        row.append(and_result)
    output_grid.append(row)

print("Bitwise AND of neighbors:")
for r in output_grid:
    print(r)

